// orchestrator/src/fanout.ts: the only way to start a run. Only the orchestrator calls it; a VM can't reach Temporal.
import { type Client, type Workflow, WorkflowIdConflictPolicy, WorkflowIdReusePolicy } from "@temporalio/client";
import { defineSearchAttributeKey, SearchAttributeType, type SignalDefinition, TypedSearchAttributes } from "@temporalio/common";
import { readFlag } from "./flags.js";

export const AGENT = defineSearchAttributeKey("Agent", SearchAttributeType.KEYWORD);
export const agentAttribute = (agent: string) => new TypedSearchAttributes([{ key: AGENT, value: agent }]);

export class AgentStopped extends Error {
  constructor(readonly agent: string, reason: string) {
    super(`The kill switch is on for ${agent} (${reason}), so no new run starts.`);
  }
}

const refuseIfStopped = async (agent: string): Promise<void> => {
  const flag = await readFlag(`agent:${agent}:stopped`);
  if (flag) throw new AgentStopped(agent, flag.reason);
};

/** nova:RH-1234 on ai-agents-nova. A second start for the same thing joins the open run. */
export const startRun = async (client: Client, agent: string, thing: string, wf: string | Workflow, ...args: unknown[]) => {
  await refuseIfStopped(agent);
  return client.workflow.start(wf, {
    workflowId: `${agent}:${thing}`, // nova:RH-1234 | bugfix:RH-1240
    taskQueue: `ai-agents-${agent}`, // one queue per agent: nobody starves anybody
    workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING,
    typedSearchAttributes: agentAttribute(agent), // the batch stop finds runs by Agent
    args,
  });
};

/** The same ID, queue and Agent, for triggers that carry news: signal the open run, or start it and then signal it. */
export const startOrSignal = async <T>(
  client: Client, agent: string, thing: string, wf: string | Workflow, input: unknown,
  signal: SignalDefinition<[T]>, signalArg: T,
) => {
  await refuseIfStopped(agent);
  return client.workflow.signalWithStart(wf, {
    workflowId: `${agent}:${thing}`, // cifix:fcp:<fingerprint> | upgrade:fcp:pr-<n>
    taskQueue: `ai-agents-${agent}`,
    typedSearchAttributes: agentAttribute(agent),
    workflowIdReusePolicy: WorkflowIdReusePolicy.REJECT_DUPLICATE, // a root cause whose run closed never starts again
    args: [input],
    signal,
    signalArgs: [signalArg],
  });
};

// orchestrator/src/flags.ts: read a flag from the broker's flag store (internal port, orchestrator only).
// Names: agent:<agent>:stopped (the kill switch). G5 adds routine:<name>:paused and routines:fixers:paused.
import { brokerInternal } from "./broker-internal.js";

export interface Flag {
  name: string;
  value: string;
  reason: string;
  setBy: string;
  setAt: string;
}

/** null when the flag is not set. */
export const readFlag = (name: string): Promise<Flag | null> =>
  brokerInternal.get<Flag | null>(`/internal/flags/${encodeURIComponent(name)}`);

// orchestrator/src/temporal.ts: one Temporal client per process, used by activities and triggers.
import { Client, Connection } from "@temporalio/client";

let client: Promise<Client> | undefined;

export const temporalClient = (): Promise<Client> =>
  (client ??= Connection.connect({ address: process.env.TEMPORAL_ADDRESS ?? "localhost:7233" }).then(
    (connection) => new Client({ connection, namespace: "ai-agents" }),
  ));

// orchestrator/src/workflows/slots.ts: workflow code (deterministic). One slots:<agent> workflow per agent, forever.
import {
  condition, continueAsNew, defineSignal, getExternalWorkflowHandle, log, proxyLocalActivities, setHandler, workflowInfo,
} from "@temporalio/workflow";
import type * as activities from "../activities/index.js";

export const SLOTS: Record<string, number> = { nova: 3, cifix: 2, upgrade: 2, flaky: 1, bugfix: 2, health: 1, security: 1 };
export const request = defineSignal<[workflowId: string]>("request");
export const release = defineSignal<[workflowId: string]>("release"); // when the VM is parked or released
export const slotGranted = defineSignal("slotGranted");
const { stillOpen } = proxyLocalActivities<typeof activities>({ startToCloseTimeout: "1 minute" });

export async function slots(agent: string, holders: string[] = [], waiting: string[] = []): Promise<void> {
  setHandler(request, (id) => {
    if (!holders.includes(id) && !waiting.includes(id)) waiting.push(id); // a retried request is not a second place in line
  });
  setHandler(release, (id) => {
    holders = holders.filter((h) => h !== id);
    waiting = waiting.filter((w) => w !== id); // stopped while still in line
  });
  while (!workflowInfo().continueAsNewSuggested) {
    const free = await condition(() => waiting.length > 0 && holders.length < (SLOTS[agent] ?? 1), "1 hour");
    if (!free) {
      holders = await stillOpen(holders); // a terminated run never ran its finally: take its slot back
      continue;
    }
    const holder = waiting.shift()!;
    holders.push(holder);
    try {
      await getExternalWorkflowHandle(holder).signal(slotGranted);
    } catch (err) {
      holders = holders.filter((h) => h !== holder); // it ended while it waited in line
      log.warn("slot holder is gone", { agent, holder, err: String(err) });
    }
  }
  await continueAsNew<typeof slots>(agent, holders, waiting);
}

// orchestrator/src/workflows/with-slot.ts: workflow code. How ticketToPr and routineRun hold a VM slot.
import { CancellationScope, condition, getExternalWorkflowHandle, setHandler, workflowInfo } from "@temporalio/workflow";
import { release, request, slotGranted } from "./slots.js";

/** Wait in line for one of the agent's VM slots. Call it before acquireSandbox and before wakeSandbox. */
export const takeSlot = async (agent: string): Promise<void> => {
  let granted = false;
  setHandler(slotGranted, () => {
    granted = true;
  });
  await getExternalWorkflowHandle(`slots:${agent}`).signal(request, workflowInfo().workflowId);
  try {
    await condition(() => granted);
  } catch (err) {
    await giveSlot(agent); // cancelled while in line: leave the line
    throw err;
  }
};

/** Give the slot back. Call it after parkSandbox and after releaseSandbox; it runs even when the run is cancelled. */
export const giveSlot = (agent: string): Promise<void> =>
  CancellationScope.nonCancellable(() =>
    getExternalWorkflowHandle(`slots:${agent}`).signal(release, workflowInfo().workflowId),
  );

export const withSlot = async <T>(agent: string, fn: () => Promise<T>): Promise<T> => {
  await takeSlot(agent);
  try {
    return await fn();
  } finally {
    await giveSlot(agent);
  }
};

// orchestrator/src/workflows/kill-switch.ts: workflow code. Read the kill switch before every step.
import { proxyLocalActivities } from "@temporalio/workflow";
import type * as activities from "../activities/index.js";

// A local activity: it runs in the worker that runs the workflow, so the check costs milliseconds.
const { agentStopped } = proxyLocalActivities<typeof activities>({ startToCloseTimeout: "30 seconds" });

/** true: end the run cleanly before the next step and keep the branch and notes. */
export const killed = (agent: string): Promise<boolean> => agentStopped(agent);

// orchestrator/src/activities/fanout.ts: activities for the fan-out walls (plain async functions; Node APIs allowed).
import { WorkflowNotFoundError } from "@temporalio/client";
import { readFlag } from "../flags.js";
import { temporalClient } from "../temporal.js";

export const agentStopped = async (agent: string): Promise<boolean> => (await readFlag(`agent:${agent}:stopped`)) !== null;

/** The slot holders whose runs are still running. A run that was terminated never gave its slot back. */
export const stillOpen = async (workflowIds: string[]): Promise<string[]> => {
  const client = await temporalClient();
  const open: string[] = [];
  for (const id of workflowIds) {
    const status = await client.workflow.getHandle(id).describe().then(
      (d) => d.status.name,
      (err: unknown) => {
        if (err instanceof WorkflowNotFoundError) return "NOT_FOUND";
        throw err; // Temporal unreachable: keep every holder rather than free a slot by mistake
      },
    );
    if (status === "RUNNING") open.push(id);
  }
  return open;
};

// broker/src/flags.ts: the flag store behind the kill switch. Mount it on the internal listener only, next to
// POST /internal/runs; the sandbox-facing port never serves it (only orchestrator-worker reaches the internal port).
import type { IncomingMessage, ServerResponse } from "node:http";
import type { Pool } from "pg";

export interface Flag { name: string; value: string; reason: string; setBy: string; setAt: string }

const NAME = /^(agent|routine|routines):[a-z0-9-]+:[a-z_]+$/; // agent:nova:stopped, routine:fe-ci-fixer:paused
const json = (res: ServerResponse, body: unknown) =>
  void res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify(body));

export const ensureFlagsTable = (db: Pool) =>
  db.query(`CREATE TABLE IF NOT EXISTS flags (name text PRIMARY KEY, value text NOT NULL, reason text NOT NULL,
    set_by text NOT NULL, set_at timestamptz NOT NULL DEFAULT now())`);

const readBody = async (req: IncomingMessage): Promise<string> => {
  let body = "";
  for await (const chunk of req) {
    body += String(chunk);
    if (body.length > 4096) throw new Error("flag body too large");
  }
  return body;
};

/** GET | PUT | DELETE /internal/flags/<name>. GET answers null when the flag is not set. */
export const flagRoute = async (req: IncomingMessage, res: ServerResponse, db: Pool, name: string): Promise<void> => {
  if (!NAME.test(name)) return void res.writeHead(400).end("bad flag name");
  if (req.method === "GET") {
    const { rows } = await db.query<Flag>(
      `SELECT name, value, reason, set_by AS "setBy", set_at AS "setAt" FROM flags WHERE name = $1`, [name]);
    return json(res, rows[0] ?? null);
  }
  if (req.method === "PUT") {
    const { value = "on", reason, setBy } = JSON.parse(await readBody(req)) as Partial<Flag>;
    if (!reason || !setBy) return void res.writeHead(400).end("reason and setBy are required");
    await db.query(`INSERT INTO flags (name, value, reason, set_by) VALUES ($1, $2, $3, $4)
      ON CONFLICT (name) DO UPDATE SET value = $2, reason = $3, set_by = $4, set_at = now()`, [name, value, reason, setBy]);
    return json(res, { ok: true });
  }
  if (req.method === "DELETE") {
    await db.query("DELETE FROM flags WHERE name = $1", [name]);
    return json(res, { ok: true });
  }
  res.writeHead(405).end();
};

// orchestrator/src/main.ts: the orchestrator-worker process. One Temporal worker per task queue, one shared bundle.
import { fileURLToPath } from "node:url";
import { WorkflowIdConflictPolicy } from "@temporalio/client";
import { bundleWorkflowCode, NativeConnection, Worker } from "@temporalio/worker";
import * as activities from "./activities/index.js";
import { temporalClient } from "./temporal.js";
import { SLOTS, slots } from "./workflows/slots.js";

const QUEUES = ["nova", "cifix", "upgrade", "flaky", "bugfix", "health", "security", "orchestrator"];

/** Start slots:<agent> for every agent. Safe on every worker start: USE_EXISTING joins the one that runs. */
const ensureSlots = async (): Promise<void> => {
  const client = await temporalClient();
  for (const agent of Object.keys(SLOTS)) {
    await client.workflow.start(slots, {
      workflowId: `slots:${agent}`,
      taskQueue: "ai-agents-orchestrator", // housekeeping queue, like the Jira polls
      args: [agent],
      workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING,
    });
  }
};

const connection = await NativeConnection.connect({ address: process.env.TEMPORAL_ADDRESS ?? "localhost:7233" });
const workflowBundle = await bundleWorkflowCode({
  workflowsPath: fileURLToPath(new URL("./workflows/index.js", import.meta.url)),
});
const workers = await Promise.all(
  QUEUES.map((q) => Worker.create({ connection, namespace: "ai-agents", taskQueue: `ai-agents-${q}`, workflowBundle, activities })),
);
await ensureSlots();
// G3-28: await ensureSchedules(await temporalClient());
await Promise.all(workers.map((w) => w.run())); // each worker polls only its own queue

