// orchestrator/test/workflows/fanout.ts: small workflows for the fan-out tests, bundled with the real slots workflow.
import { condition, defineQuery, defineSignal, proxyActivities, setHandler } from "@temporalio/workflow";
import { killed } from "../../src/workflows/kill-switch.js";
import { giveSlot, takeSlot } from "../../src/workflows/with-slot.js";
export { slots } from "../../src/workflows/slots.js";

export const done = defineSignal("done");
export const hasSlot = defineQuery<boolean>("hasSlot");

/** Stays open until "done", like a run that waits for plan approval. */
export async function waitForDone(): Promise<void> {
  let finished = false;
  setHandler(done, () => void (finished = true));
  await condition(() => finished);
}

/** Takes a Nova slot and holds it until "done". */
export async function holdSlot(): Promise<void> {
  let finished = false;
  let mine = false;
  setHandler(done, () => void (finished = true));
  setHandler(hasSlot, () => mine);
  await takeSlot("nova");
  mine = true;
  await condition(() => finished);
  await giveSlot("nova");
}

const { step } = proxyActivities<{ step(n: number): Promise<void> }>({ startToCloseTimeout: "1 minute" });

/** Three steps with the kill switch read before each one, as ticketToPr does. */
export async function threeSteps(): Promise<string> {
  for (const n of [1, 2, 3]) {
    if (await killed("nova")) return `stopped before step ${n}`;
    await step(n);
  }
  return "done";
}

// orchestrator/test/fanout.test.ts: run with `npm test`. Starts a local Temporal dev server through the testing package.
import assert from "node:assert/strict";
import { after, before, mock, test } from "node:test";
import { setTimeout as sleep } from "node:timers/promises";
import { fileURLToPath } from "node:url";
import { TestWorkflowEnvironment } from "@temporalio/testing";
import { Worker } from "@temporalio/worker";
import { agentStopped } from "../src/activities/fanout.js";
import { brokerInternal } from "../src/broker-internal.js";
import { AgentStopped, startRun } from "../src/fanout.js";
import { done, hasSlot } from "./workflows/fanout.js";

const stopped = new Set<string>(); // the fake flag store: flag names that are on
mock.method(brokerInternal, "get", (async (path: string) =>
  stopped.has(decodeURIComponent(path.split("/").at(-1)!)) ? { reason: "test" } : null) as typeof brokerInternal.get);

let env: TestWorkflowEnvironment, worker: Worker, running: Promise<void>;
const eventually = async (check: () => Promise<boolean>) => {
  for (let i = 0; i < 100 && !(await check()); i++) await sleep(100);
  assert.ok(await check());
};

before(async () => {
  env = await TestWorkflowEnvironment.createLocal({ server: { extraArgs: ["--search-attribute", "Agent=Keyword"] } });
  worker = await Worker.create({
    connection: env.nativeConnection, taskQueue: "ai-agents-nova",
    workflowsPath: fileURLToPath(new URL("./workflows/fanout.ts", import.meta.url)),
    activities: {
      agentStopped, stillOpen: async (ids: string[]) => ids,
      step: async (n: number) => void (n === 1 && stopped.add("agent:nova:stopped")), // the switch flips during step 1
    },
  });
  running = worker.run();
});
after(async () => {
  worker.shutdown();
  await running;
  await env.teardown();
});

test("two starts for the same ticket give one run", async () => {
  const a = await startRun(env.client, "nova", "RH-1234", "waitForDone");
  const b = await startRun(env.client, "nova", "RH-1234", "waitForDone"); // the poll, then /nova in Slack
  assert.equal(a.firstExecutionRunId, b.firstExecutionRunId);
  await a.signal(done);
});

test("a 4th Nova ticket waits for a slot until one is given back", async () => {
  await env.client.workflow.start("slots", { workflowId: "slots:nova", taskQueue: "ai-agents-nova", args: ["nova"] });
  const runs = await Promise.all([1, 2, 3, 4].map((n) =>
    env.client.workflow.start("holdSlot", { workflowId: `nova:T-${n}`, taskQueue: "ai-agents-nova" })));
  const slotsHeld = () => Promise.all(runs.map((r) => r.query(hasSlot)));
  await eventually(async () => (await slotsHeld()).filter(Boolean).length === 3); // the line order is not fixed
  const held = await slotsHeld();
  const waiter = runs[held.indexOf(false)];
  await runs[held.indexOf(true)].signal(done); // one run finishes and gives its slot back
  await eventually(() => waiter.query(hasSlot));
});

test("the kill switch stops a run between steps and refuses new starts", async () => {
  const result = await env.client.workflow.execute("threeSteps", { workflowId: "nova:RH-77", taskQueue: "ai-agents-nova" });
  assert.equal(result, "stopped before step 2");
  await assert.rejects(startRun(env.client, "nova", "RH-78", "waitForDone"), AgentStopped);
});
